#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef struct Node { int d; struct Node *p, *n; } Node;
Node *h=NULL, *t=NULL;
int sz=0;
void ib(int v) { Node* nn=malloc(sizeof(Node)); nn->d=v; nn->n=h; nn->p=NULL; if(h) h->p=nn; else t=nn; h=nn; sz++; }
void ie(int v) { Node* nn=malloc(sizeof(Node)); nn->d=v; nn->n=NULL; nn->p=t; if(t) t->n=nn; else h=nn; t=nn; sz++; }
void im(int pos, int v) { if(pos<1 || pos>sz+1) { printf("Invalid\n"); return; } if(pos==1) { ib(v); return; } if(pos==sz+1) { ie(v); return; } Node* nn=malloc(sizeof(Node)); nn->d=v; Node* c=h; for(int i=1; i<pos-1; i++) c=c->n; nn->n=c->n; nn->p=c; if(c->n) c->n->p=nn; c->n=nn; sz++; }
void disp() { if(!h) { printf("Empty\n"); return; } Node* c=h; while(c) { printf("%d%c", c->d, c->n?' ':'\n'); c=c->n; } }
int main() { int n, v, p; char op[20]; if(scanf("%d", &n)!=1) return 0; while(n--) { scanf("%s", op); if(!strcmp(op, "ins_beg")) { scanf("%d", &v); ib(v); } else if(!strcmp(op, "ins_end")) { scanf("%d", &v); ie(v); } else if(!strcmp(op, "ins_mid")) { scanf("%d%d", &p, &v); im(p, v); } else if(!strcmp(op, "display")) disp(); } return 0; }

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef struct Node { int d; struct Node *p, *n; } Node;
Node *h=NULL, *t=NULL;
int sz=0;
void ie(int v) { Node* nn=malloc(sizeof(Node)); nn->d=v; nn->n=NULL; nn->p=t; if(t) t->n=nn; else h=nn; t=nn; sz++; }
void db() { if(!h) { printf("Underflow\n"); return; } Node* tm=h; h=h->n; if(h) h->p=NULL; else t=NULL; free(tm); sz--; }
void de() { if(!t) { printf("Underflow\n"); return; } Node* tm=t; t=t->p; if(t) t->n=NULL; else h=NULL; free(tm); sz--; }
void dm(int pos) { if(pos<1 || pos>sz) { printf("Invalid\n"); return; } if(pos==1) { db(); return; } if(pos==sz) { de(); return; } Node* c=h; for(int i=1; i<pos; i++) c=c->n; c->p->n=c->n; if(c->n) c->n->p=c->p; free(c); sz--; }
void disp() { if(!h) { printf("Empty\n"); return; } Node* c=h; while(c) { printf("%d%c", c->d, c->n?' ':'\n'); c=c->n; } }
int main() { int n, v, p; char op[20]; if(scanf("%d", &n)!=1) return 0; while(n--) { scanf("%s", op); if(!strcmp(op, "ins_end")) { scanf("%d", &v); ie(v); } else if(!strcmp(op, "del_beg")) db(); else if(!strcmp(op, "del_end")) de(); else if(!strcmp(op, "del_mid")) { scanf("%d", &p); dm(p); } else if(!strcmp(op, "display")) disp(); } return 0; }
